const { parentType, parentId, title, properties, content, children } = $.input;
if (!parentType || !parentId || !title) throw new Error('parentType, parentId, and title are required');

const body = {};

// Set parent
if (parentType === 'database') {
  body.parent = { database_id: parentId };
  // For database pages, title goes in properties
  body.properties = properties ? { ...properties } : {};
  // Find the title property or default to 'Name' or 'title'
  const titleProp = body.properties.Name ? 'Name' : (body.properties.title ? 'title' : 'Name');
  if (!body.properties[titleProp]) {
    body.properties[titleProp] = { title: [{ text: { content: title } }] };
  }
} else {
  body.parent = { page_id: parentId };
  body.properties = { title: [{ text: { content: title } }] };
}

// Set children (content blocks)
if (children && children.length > 0) {
  body.children = children;
} else if (content) {
  body.children = [{
    object: 'block',
    type: 'paragraph',
    paragraph: {
      rich_text: [{ type: 'text', text: { content } }]
    }
  }];
}

return body;

const resp = $.steps.createPage.response || {};
const url = resp.url || '';
return {
  pageId: resp.id || '',
  url,
  parentType: $.input.parentType,
  title: $.input.title,
  created: !!resp.id,
  createdTime: resp.created_time || '',
  summary: resp.id
    ? `Created page "${$.input.title}" in Notion`
    : 'Failed to create page'
};
